sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var method = request.httpMethod;
    try {
        var body;
        if (method === 'GET' && request.pathParams.sys_id) {
            body = getOne(request.pathParams.sys_id);
        } else if (method === 'GET') {
            body = getList(request.queryParams);
        } else if (method === 'POST') {
            body = createComplaint(request.body.data);
        } else {
            response.setStatus(405);
            return { success: false, error: 'Method not allowed' };
        }
        response.setStatus(body.success ? 200 : 400);
        return body;
    } catch (e) {
        response.setStatus(500);
        return { success: false, error: e.message };
    }

    function getOne(sysId) {
        var gr = new GlideRecord('sn_customerservice_case');
        if (!gr.get(sysId)) {
            return { success: false, error: 'Complaint not found' };
        }
        return { success: true, result: toObj(gr) };
    }

    function getList(qp) {
        var gr = new GlideRecord('sn_customerservice_case');
        if (qp.store) gr.addQuery('x_2145749_qc_dark_store', qp.store);
        if (qp.status) gr.addQuery('state', qp.status);
        if (qp.priority) gr.addQuery('priority', qp.priority);
        gr.orderByDesc('sys_created_on');
        var limit = parseInt(qp.limit, 10) || 50;
        var offset = parseInt(qp.offset, 10) || 0;
        gr.chooseWindow(offset, offset + limit);
        gr.query();
        var results = [];
        while (gr.next()) {
            results.push(toObj(gr));
        }
        return { success: true, result: results };
    }

    function createComplaint(data) {
        if (!data || !data.store || !data.complaint_type) {
            return { success: false, error: 'store and complaint_type are required' };
        }
        var gr = new GlideRecord('sn_customerservice_case');
        gr.initialize();
        gr.x_2145749_qc_dark_store = data.store;
        gr.x_2145749_qc_order_number = data.order_number || '';
        gr.x_2145749_qc_complaint_type = data.complaint_type;
        if (data.order_value) gr.x_2145749_qc_order_value = data.order_value;
        gr.short_description = data.description || data.complaint_type;
        gr.priority = derivePriority(data.order_value);
        // ai_urgency_score field does not exist on this table (confirmed) - not written
        var sysId = gr.insert();
        if (!sysId) {
            return { success: false, error: 'Insert failed' };
        }
        return getOne(sysId);
    }

    function derivePriority(orderValue) {
        var v = parseFloat(orderValue) || 0;
        if (v >= 1000) return '1';
        if (v >= 300) return '2';
        return '3';
    }

    function toObj(gr) {
        return {
            sys_id: gr.getUniqueValue(),
            store: gr.x_2145749_qc_dark_store.getDisplayValue(),
            order_number: gr.x_2145749_qc_order_number.toString(),
            complaint_type: gr.x_2145749_qc_complaint_type.toString(),
            priority: gr.priority.toString(),
            state: gr.state.getDisplayValue(),
            short_description: gr.short_description.toString(),
            created: gr.sys_created_on.toString()
        };
    }
})(request, response);
